#
# Mostly Ai Generated - Start
# Regenerate the Bazel NuGet dependency tree (deps/):
#   1) run rules_dotnet's paket2bazel against paket.dependencies/paket.lock,
#   2) emit deps/Api_deps.bzl, the per-project DEPS list that Api/BUILD.bazel
#      loads, derived 1:1 from Api/paket.references so the BUILD label list
#      cannot drift from the paket definition.
# deps/BUILD.bazel is hand-maintained and never generated by this script.
set -euo pipefail

out_dir="$1"
root="$(pwd)"

mkdir -p "$out_dir"

bazel run @rules_dotnet//tools/paket2bazel -- \
  --dependencies-file "$root/paket.dependencies" \
  --output-folder "$out_dir" >/dev/null

# Tag text is assembled at runtime so REUSE does not treat these echo lines as
# this script's own SPDX headers.
spdx_tag='SPDX-'
{
  echo "# ${spdx_tag}FileCopyrightText: 2026 Alper Çelik <alper@alper-celik.dev>"
  echo '#'
  echo "# ${spdx_tag}License-Identifier: AGPL-3.0-or-later OR Apache-2.0"
  echo '#'
  echo '# Mostly Ai Generated - Start'
  echo '# DEPS labels derived from Api/paket.references by `just bazel-sync-deps`.'
  echo '# Regenerate with `just bazel-sync-deps` after changing paket files; the'
  echo '# freshness check (`just bazel-deps-check`) enforces it.'
  echo 'DEPS = ['
  awk 'NF && $0 !~ /^#/ {print "    \"@paket.main//" tolower($1) "\","}' \
    "$root/Api/paket.references"
  echo ']'
  echo '# Mostly Ai Generated - End'
} > "$out_dir/Api_deps.bzl"
# Mostly Ai Generated - End
